    def retranslateUi(self, Form):
        _translate = QtCore.QCoreApplication.translate
        self.btn_batch_export_structure.setToolTip(_translate("Form", "<p>Collects the structure results of every .tif/.tiff file below the root folder into one Excel table, one row per file: its metadata and 43 standard structure metrics (cell mask, Z-bands, sarcomeres, myofibrils, domains). Run the batch structure analysis first; metrics not analysed stay empty. For movies a cell holds the mean over the analysed frames, and a 'per_frame' sheet lists each frame. A 'metrics' sheet gives units and descriptions. You pick the file name.</p>"))
        self.chk_do_domains.setToolTip(_translate("Form", "<p>For each file, groups nearby sarcomere vectors with similar orientation into domains (regions of aligned sarcomeres) and measures their number, area, orientation order and mean sarcomere length. Uses the domain settings of the Structure tab. Needs sarcomere vectors, so keep 'Analyse Vectors' on unless the files already have them. Default on.</p>"))
        self.chk_do_myofibrils.setToolTip(_translate("Form", "<p>For each file, traces myofibrils by linking sarcomere vectors that line up head to tail, and measures myofibril length (mean, maximum, spread) and bending. Uses the myofibril settings of the Structure tab. Needs sarcomere vectors, so keep 'Analyse Vectors' on unless the files already have them. Default on.</p>"))
        self.chk_do_vectors.setToolTip(_translate("Form", "<p>For each file, finds the sarcomere vectors (one per M-band midline pixel, pointing from Z-band to Z-band) and measures sarcomere length, orientation and orientation order. Uses the vector settings of the Structure tab (length limits, line width, outlier check). Needed for the myofibril and domain analyses. Afterwards the log warns if the pixel size looks about 2x too small. Default on.</p>"))
        self.chk_do_zbands.setToolTip(_translate("Form", "<p>For each file, cuts the predicted Z-band mask into single Z-bands and measures their number, length, intensity, contrast, orientation order and lateral alignment with neighbouring Z-bands. Uses the threshold, minimum length and maximum axial offset of the Structure tab; the other Z-band settings there are not passed to the batch, which uses their defaults. Untick to save time when you do not need Z-band metrics. Default on.</p>"))
        self.le_batch_axes.setToolTip(_translate("Form", "<p>Order of the image dimensions, one letter each: T time, Z depth, C channel, Y rows, X columns (e.g. TYX for a movie, YX for a single image, TCYX for a multi-channel movie). Used only with 'Override for all files'. Leave it empty to read the order from each file (OME or ImageJ metadata), which is usually right; fill it in only when files are read wrongly, e.g. movie frames taken as channels. Like the channel, it only affects files read for the first time. Default empty (automatic).</p>"))
        self.label_9.setToolTip(_translate("Form", "<p>Order of the image dimensions, one letter each: T time, Z depth, C channel, Y rows, X columns (e.g. TYX for a movie, YX for a single image, TCYX for a multi-channel movie). Used only with 'Override for all files'. Leave it empty to read the order from each file (OME or ImageJ metadata), which is usually right; fill it in only when files are read wrongly, e.g. movie frames taken as channels. Like the channel, it only affects files read for the first time. Default empty (automatic).</p>"))
        self.sb_batch_channel.setToolTip(_translate("Form", "<p>Number of the colour channel with the sarcomere stain (Z-bands, e.g. α-actinin), counted from 0. Used only with 'Override for all files', and then for every file, so all files need the stain in the same channel. With 'Use file metadata' each file keeps its saved channel, or channel 0 with a warning. No effect on single-channel images. It is applied when a file is read for the first time; files opened or analysed before keep the channel they were read with. Default 0.</p>"))
        self.label_8.setToolTip(_translate("Form", "<p>Number of the colour channel with the sarcomere stain (Z-bands, e.g. α-actinin), counted from 0. Used only with 'Override for all files', and then for every file, so all files need the stain in the same channel. With 'Use file metadata' each file keeps its saved channel, or channel 0 with a warning. No effect on single-channel images. It is applied when a file is read for the first time; files opened or analysed before keep the channel they were read with. Default 0.</p>"))
        self.sb_thread_pool_size.setToolTip(_translate("Form", "<p>Number of files analysed at the same time. 1 analyses the files one after another. Higher values only take effect on a computer that runs the analysis on the CPU (no GPU in use) and has a thread-safe numba layer (TBB or OpenMP); with an Apple-silicon (MPS) or NVIDIA (CUDA) GPU the files always run one after another, and the log says so. Each parallel file needs its own memory, so keep it low for large movies. Default 1.</p>"))
        self.label_5.setToolTip(_translate("Form", "<p>Number of files analysed at the same time. 1 analyses the files one after another. Higher values only take effect on a computer that runs the analysis on the CPU (no GPU in use) and has a thread-safe numba layer (TBB or OpenMP); with an Apple-silicon (MPS) or NVIDIA (CUDA) GPU the files always run one after another, and the log says so. Each parallel file needs its own memory, so keep it low for large movies. Default 1.</p>"))
        self.btn_search.setToolTip(_translate("Form", "<p>Choose the root folder in a folder dialog. Its path is written into the field on the left; nothing is analysed until you press 'Run batch structure analysis'.</p>"))
        self.le_root_directory.setToolTip(_translate("Form", "<p>Folder with the images to analyse. Every .tif/.tiff file in this folder and in all its subfolders is processed; mask files named zbands.tif, mbands.tif, cell_mask.tif, orientation.tif and sarcomere_mask.tif are skipped. The results of each image are saved in a &lt;name&gt;.ome.zarr folder next to that image. Type the path or use Browse…. The same folder is used by 'Export structure data to .xlsx'.</p>"))
        self.label.setToolTip(_translate("Form", "<p>Folder with the images to analyse. Every .tif/.tiff file in this folder and in all its subfolders is processed; mask files named zbands.tif, mbands.tif, cell_mask.tif, orientation.tif and sarcomere_mask.tif are skipped. The results of each image are saved in a &lt;name&gt;.ome.zarr folder next to that image. Type the path or use Browse…. The same folder is used by 'Export structure data to .xlsx'.</p>"))
        Form.setWindowTitle(_translate("Form", "Form"))
        self.label_6.setText(_translate("Form", "First, adjust the settings in the \"Structure\" and \"Motion\" tabs using a single, representative image/movie. The finalized parameters will be used to process the entire batch."))
        self.label.setText(_translate("Form", "Root directory"))
        self.le_root_directory.setPlaceholderText(_translate("Form", "Path of root directory of data to process"))
        self.btn_search.setText(_translate("Form", "Browse…"))
        self.label_5.setText(_translate("Form", "Thread Pool Size"))
        self.label_2.setToolTip(_translate("Form", "<p>Edge length of one image pixel, in µm per pixel. Used only with 'Override for all files': it then replaces the pixel size of every image in the batch and is saved in each image's .ome.zarr store. With 'Use file metadata' this field is ignored, and a file without its own pixel size fails (it is listed at the end). All lengths depend on it. Default 0.1 µm.</p>"))
        self.label_2.setText(_translate("Form", "Pixel size [µm]"))
        self.dsb_pixel_size.setToolTip(_translate("Form", "<p>Edge length of one image pixel, in µm per pixel. Used only with 'Override for all files': it then replaces the pixel size of every image in the batch and is saved in each image's .ome.zarr store. With 'Use file metadata' this field is ignored, and a file without its own pixel size fails (it is listed at the end). All lengths depend on it. Default 0.1 µm.</p>"))
        self.label_3.setToolTip(_translate("Form", "<p>Time between two frames of a movie, in seconds per frame (1 / frame rate; 0.01 s at 100 frames/s). Used only with 'Override for all files': it then replaces the frame time of every image in the batch and is saved with it. With 'Use file metadata' it is ignored. The structure analysis does not need it; it sets the time scale of any later motion analysis (velocities, beating rate, contraction times). Default 0.1 s.</p>"))
        self.label_3.setText(_translate("Form", "Frame time [s]"))
        self.dsb_frame_time.setToolTip(_translate("Form", "<p>Time between two frames of a movie, in seconds per frame (1 / frame rate; 0.01 s at 100 frames/s). Used only with 'Override for all files': it then replaces the frame time of every image in the batch and is saved with it. With 'Use file metadata' it is ignored. The structure analysis does not need it; it sets the time scale of any later motion analysis (velocities, beating rate, contraction times). Default 0.1 s.</p>"))
        self.label_8.setText(_translate("Form", "Channel"))
        self.label_9.setText(_translate("Form", "Axes"))
        self.chk_force_override.setToolTip(_translate("Form", "<p>When ticked, the pixel size, frame time, channel and axes entered above replace those of every image in the batch and are saved in each image's .ome.zarr store. When not ticked, each image keeps its own values and these fields are ignored. Default off.</p>"))
        self.chk_force_override.setText(_translate("Form", "Force overwrite metadata"))
        self.chk_delete_intermediate_masks.setToolTip(_translate("Form", "<p>After each file is analysed, deletes the predicted masks (Z-bands, M-bands, orientation map, cell mask, sarcomere mask) from its .ome.zarr store to save disk space. The image and all measured results are kept, so the export is unaffected. For movies the Z-band masks are kept, because the motion analysis re-measures lengths on them. Without the masks the viewer cannot show them, and re-running Z-band or vector analysis needs the detection again. Default on.</p>"))
        self.chk_delete_intermediate_masks.setText(_translate("Form", "Delete intermediate masks from the store"))
        self.chk_recalculate_for_motion.setToolTip(_translate("Form", "<p>Only for 'Batch motion analysis'. When on, every movie is analysed again from the start before tracking: sarcomere detection and sarcomere vectors on all frames, plus myofibrils or domains at the reference frame when the tracks are grouped by them, with the settings of the Structure tab. When off (default), these steps run only for movies that lack them, so movies already analysed on all frames keep their results.</p><p>The batch never runs the 3D U-Net; a movie that already has its Z-bands uses them for the vectors.</p>"))
        self.chk_recalculate_for_motion.setText(_translate("Form", "Run structure prerequisites before motion analysis"))
        self.groupBox_2.setTitle(_translate("Form", "Structure"))
        self.chk_do_zbands.setText(_translate("Form", "Analyze Z-Bands"))
        self.chk_do_vectors.setText(_translate("Form", "Analyze Vectors"))
        self.chk_do_myofibrils.setText(_translate("Form", "Analyze Myofibrils"))
        self.chk_do_domains.setText(_translate("Form", "Analyze Domains"))
        self.btn_batch_processing_structure.setToolTip(_translate("Form", "<p>Analyses every .tif/.tiff file below the root folder. For each file it runs the sarcomere detection with the Structure tab settings (network, frames, patch size, contrast clipping, rescale factor), then the steps ticked under Structure, and saves the results in &lt;name&gt;.ome.zarr next to the image, replacing earlier results of those steps. Files that fail are listed at the end; the others are saved. Check the settings on one representative file first.</p>"))
        self.btn_batch_processing_structure.setText(_translate("Form", "Run batch structure analysis"))
        self.btn_batch_processing_motion.setToolTip(_translate("Form", "<p>Runs the motion analysis on every movie in the folder and its subfolders, one after another: tracking, grouping and analysis with the settings of the Motion tab (steps 1 to 3). Movies without sarcomere vectors on all frames, or without myofibrils or domains at the reference frame when grouping by them, get these structure steps first (see 'Run structure prerequisites'). Grouping by LOI detects the LOIs automatically.</p><p>Each movie needs a frame time; single images are skipped with an error. Results are saved in each .ome.zarr store; open a movie to look at them. Long: several minutes per movie.</p>"))
        self.btn_batch_processing_motion.setText(_translate("Form", "Batch motion analysis"))
        self.btn_batch_export_structure.setText(_translate("Form", "Export structure data to .xlsx"))


